package ops

import (
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"path"
	"regexp"
	"sort"
	"strconv"
	"strings"
	"time"
)

// RunnerConfig is /etc/vpnmap-ops/ops.yaml on one server: everything the
// runner there may touch. It is generated by `vpnmap ops config <node>` from
// the node's `ops:` block plus values derived from the topology, installed
// root-owned by the owner, and never written by the hub. The hub keeps an
// identical copy (in the bundle) to refuse bad requests early.
type RunnerConfig struct {
	Node       string      `json:"node" yaml:"node"`
	Containers []Container `json:"containers,omitempty" yaml:"containers,omitempty"`
	Units      []Unit      `json:"units,omitempty" yaml:"units,omitempty"`
	Logs       []Log       `json:"logs,omitempty" yaml:"logs,omitempty"`
	TCPTargets []string    `json:"tcp_targets,omitempty" yaml:"tcp_targets,omitempty"`
	Ports      []int       `json:"ports,omitempty" yaml:"ports,omitempty"`
	WG         []WG        `json:"wg,omitempty" yaml:"wg,omitempty"`
	Scripts    []Script    `json:"scripts,omitempty" yaml:"scripts,omitempty"`
}

// Container is a docker container the runner may inspect (and restart).
type Container struct {
	Name     string `json:"name" yaml:"name"`
	Restart  bool   `json:"restart,omitempty" yaml:"restart,omitempty"`
	Cooldown string `json:"cooldown,omitempty" yaml:"cooldown,omitempty"`
}

// Unit is a systemd unit the runner may inspect (and restart).
type Unit struct {
	Name     string `json:"name" yaml:"name"`
	Restart  bool   `json:"restart,omitempty" yaml:"restart,omitempty"`
	Cooldown string `json:"cooldown,omitempty" yaml:"cooldown,omitempty"`
}

// Log is a file the runner may tail, addressed by id.
type Log struct {
	ID   string `json:"id" yaml:"id"`
	Path string `json:"path" yaml:"path"`
}

// WG is a WireGuard interface, optionally inside a network namespace.
type WG struct {
	Iface string `json:"iface" yaml:"iface"`
	Netns string `json:"netns,omitempty" yaml:"netns,omitempty"`
}

// Script is a root-owned executable in /etc/vpnmap-ops/actions.d/<id>.
type Script struct {
	ID       string  `json:"id" yaml:"id"`
	Kind     string  `json:"kind" yaml:"kind"`
	Params   []Param `json:"params,omitempty" yaml:"params,omitempty"`
	Timeout  string  `json:"timeout,omitempty" yaml:"timeout,omitempty"`
	Cooldown string  `json:"cooldown,omitempty" yaml:"cooldown,omitempty"`
}

// ScriptDir is where the owner installs action scripts.
const ScriptDir = "/etc/vpnmap-ops/actions.d"

// Defaults and limits.
const (
	DefaultScriptTimeout = 30 * time.Second
	MaxScriptTimeout     = 120 * time.Second
	MaxOutput            = 64 << 10
)

// Hash is a short content hash of the config. The runner reports it with
// every answer; the hub compares it with the hash of the applied topology.
func (c *RunnerConfig) Hash() string {
	n := c.Normalized()
	raw, _ := json.Marshal(n)
	sum := sha256.Sum256(raw)
	return hex.EncodeToString(sum[:])[:16]
}

// Normalized returns a copy with every list sorted, so the same data always
// gives the same file and hash.
func (c *RunnerConfig) Normalized() *RunnerConfig {
	n := *c
	n.Containers = append([]Container(nil), c.Containers...)
	sort.Slice(n.Containers, func(i, j int) bool { return n.Containers[i].Name < n.Containers[j].Name })
	n.Units = append([]Unit(nil), c.Units...)
	sort.Slice(n.Units, func(i, j int) bool { return n.Units[i].Name < n.Units[j].Name })
	n.Logs = append([]Log(nil), c.Logs...)
	sort.Slice(n.Logs, func(i, j int) bool { return n.Logs[i].ID < n.Logs[j].ID })
	n.TCPTargets = append([]string(nil), c.TCPTargets...)
	sort.Strings(n.TCPTargets)
	n.Ports = append([]int(nil), c.Ports...)
	sort.Ints(n.Ports)
	n.WG = append([]WG(nil), c.WG...)
	sort.Slice(n.WG, func(i, j int) bool { return n.WG[i].Netns+"/"+n.WG[i].Iface < n.WG[j].Netns+"/"+n.WG[j].Iface })
	n.Scripts = append([]Script(nil), c.Scripts...)
	sort.Slice(n.Scripts, func(i, j int) bool { return n.Scripts[i].ID < n.Scripts[j].ID })
	return &n
}

var reScriptID = regexp.MustCompile(`^[a-z0-9][a-z0-9-]{0,62}$`)

// Validate checks the config itself. The runner refuses to start on error,
// so a hand-edited file cannot widen access with odd values.
func (c *RunnerConfig) Validate() error {
	if !ValidToken(c.Node) {
		return fmt.Errorf("node: %q is not a valid id", c.Node)
	}
	seen := map[string]bool{}
	once := func(kind, id string) error {
		if seen[kind+"/"+id] {
			return fmt.Errorf("%s %q is listed twice", kind, id)
		}
		seen[kind+"/"+id] = true
		return nil
	}
	for _, x := range c.Containers {
		if !ValidToken(x.Name) {
			return fmt.Errorf("container %q: not a valid name", x.Name)
		}
		if err := once("container", x.Name); err != nil {
			return err
		}
		if err := validCooldown(x.Cooldown); err != nil {
			return fmt.Errorf("container %s: %v", x.Name, err)
		}
	}
	for _, x := range c.Units {
		if !ValidToken(x.Name) {
			return fmt.Errorf("unit %q: not a valid name", x.Name)
		}
		if err := once("unit", x.Name); err != nil {
			return err
		}
		if err := validCooldown(x.Cooldown); err != nil {
			return fmt.Errorf("unit %s: %v", x.Name, err)
		}
	}
	for _, x := range c.Logs {
		if !ValidToken(x.ID) {
			return fmt.Errorf("log %q: not a valid id", x.ID)
		}
		if err := ValidLogPath(x.Path); err != nil {
			return fmt.Errorf("log %s: %v", x.ID, err)
		}
		if err := once("log", x.ID); err != nil {
			return err
		}
	}
	for _, t := range c.TCPTargets {
		if err := ValidTarget(t); err != nil {
			return err
		}
	}
	for _, p := range c.Ports {
		if p < 1 || p > 65535 {
			return fmt.Errorf("port %d out of range", p)
		}
	}
	for _, w := range c.WG {
		if !ValidToken(w.Iface) || (w.Netns != "" && !ValidToken(w.Netns)) {
			return fmt.Errorf("wg %s/%s: not a valid name", w.Netns, w.Iface)
		}
		// Requests name the interface only, so it must be unambiguous.
		if err := once("wg interface", w.Iface); err != nil {
			return err
		}
	}
	for _, s := range c.Scripts {
		if err := s.Validate(); err != nil {
			return err
		}
		if err := once("script", s.ID); err != nil {
			return err
		}
	}
	return nil
}

// Validate checks one script declaration.
func (s *Script) Validate() error {
	if !reScriptID.MatchString(s.ID) {
		return fmt.Errorf("script %q: id must be lowercase letters, digits and dashes", s.ID)
	}
	if s.Kind != Read && s.Kind != Change {
		return fmt.Errorf("script %s: kind must be read or change", s.ID)
	}
	if s.Timeout != "" {
		d, err := time.ParseDuration(s.Timeout)
		if err != nil || d <= 0 || d > MaxScriptTimeout {
			return fmt.Errorf("script %s: timeout must be a duration up to %s", s.ID, MaxScriptTimeout)
		}
	}
	if err := validCooldown(s.Cooldown); err != nil {
		return fmt.Errorf("script %s: %v", s.ID, err)
	}
	names := map[string]bool{}
	for _, p := range s.Params {
		if err := p.ValidateScriptParam(); err != nil {
			return fmt.Errorf("script %s: %v", s.ID, err)
		}
		if names[p.Name] {
			return fmt.Errorf("script %s: parameter %s is declared twice", s.ID, p.Name)
		}
		names[p.Name] = true
	}
	return nil
}

// ValidateScriptParam checks a script parameter: a valid name and exactly
// one of enum, pattern (anchored RE2) or an integer range.
func (p *Param) ValidateScriptParam() error {
	if !ValidKey(p.Name) || ReservedKeys[p.Name] {
		return fmt.Errorf("parameter %q: names are lowercase letters, digits and _ (not script, req or type)", p.Name)
	}
	n := 0
	if len(p.Enum) > 0 {
		n++
		for _, v := range p.Enum {
			if !ValidToken(v) {
				return fmt.Errorf("parameter %s: enum value %q is not a valid token", p.Name, v)
			}
		}
	}
	if p.Pattern != "" {
		n++
		if !strings.HasPrefix(p.Pattern, "^") || !strings.HasSuffix(p.Pattern, "$") {
			return fmt.Errorf("parameter %s: pattern must be anchored with ^ and $", p.Name)
		}
		if _, err := regexp.Compile(p.Pattern); err != nil {
			return fmt.Errorf("parameter %s: pattern: %v", p.Name, err)
		}
	}
	if p.Min != nil || p.Max != nil {
		n++
		if p.Min == nil || p.Max == nil || *p.Min > *p.Max {
			return fmt.Errorf("parameter %s: give both min and max (min <= max)", p.Name)
		}
	}
	if n != 1 {
		return fmt.Errorf("parameter %s: give exactly one of enum, pattern or min/max", p.Name)
	}
	return nil
}

// Accepts reports whether a value fits the parameter. Every value must also
// be a token, whatever the pattern says.
func (p *Param) Accepts(v string) bool {
	if !ValidToken(v) {
		return false
	}
	switch {
	case len(p.Enum) > 0:
		return contains(p.Enum, v)
	case p.Pattern != "":
		re, err := regexp.Compile(p.Pattern)
		return err == nil && re.MatchString(v)
	case p.Min != nil && p.Max != nil:
		n, err := strconv.Atoi(v)
		return err == nil && strconv.Itoa(n) == v && n >= *p.Min && n <= *p.Max
	}
	return false
}

func validCooldown(s string) error {
	if s == "" {
		return nil
	}
	d, err := time.ParseDuration(s)
	if err != nil || d < 0 || d > 24*time.Hour {
		return fmt.Errorf("cooldown must be a duration up to 24h")
	}
	return nil
}

// ValidLogPath: absolute, clean, no "..", only safe characters, a *.log
// file, and never in places that hold keys or credentials. Logs are read as
// root, so this is an allowlist shape plus a denylist, not a free path.
func ValidLogPath(p string) error {
	if !strings.HasPrefix(p, "/") || path.Clean(p) != p || strings.Contains(p, "..") || len(p) > 256 {
		return fmt.Errorf("path %q must be absolute and clean (no ..)", p)
	}
	if !strings.HasSuffix(p, ".log") {
		return fmt.Errorf("path %q must be a .log file", p)
	}
	for _, c := range p {
		if !(c == '/' || c == '.' || c == '_' || c == '-' || c == '@' || c >= 'a' && c <= 'z' || c >= 'A' && c <= 'Z' || c >= '0' && c <= '9') {
			return fmt.Errorf("path %q has a character that is not allowed", p)
		}
	}
	for _, bad := range []string{"/etc", "/root", "/home", "/proc", "/sys", "/dev", "/boot", "/var/lib/docker", "/run", "/tmp"} {
		if p == bad || strings.HasPrefix(p, bad+"/") {
			return fmt.Errorf("path %q is never readable through ops", p)
		}
	}
	return nil
}

var reHost = regexp.MustCompile(`^[a-z0-9]([a-z0-9.-]{0,251}[a-z0-9])?$`)

// ValidTarget accepts host:port with a lowercase host name or IPv4.
func ValidTarget(t string) error {
	host, port, ok := strings.Cut(t, ":")
	n, err := strconv.Atoi(port)
	if !ok || !reHost.MatchString(host) || strings.Contains(host, "..") || err != nil || n < 1 || n > 65535 || strconv.Itoa(n) != port {
		return fmt.Errorf("tcp target %q must be host:port", t)
	}
	return nil
}

func contains(list []string, s string) bool {
	for _, x := range list {
		if x == s {
			return true
		}
	}
	return false
}

// Allowed is a request that passed Allow: the type plus what it resolved to.
type Allowed struct {
	Type      *Type
	Request   *Request
	Container *Container
	Unit      *Unit
	Log       *Log
	Target    string
	Port      int
	WG        *WG
	Script    *Script
	// ScriptArgs are the script's own params in declaration order.
	ScriptArgs [][2]string
	// Cooldown applies to change actions (0 = none).
	Cooldown time.Duration
}

// Allow checks a request against this server's config: the type must run on
// a server, every argument must be known and allowed, and nothing extra may
// be given. It is the same check in the runner (twice: before and after
// sudo) and, mirrored in TypeScript, in the hub.
func (c *RunnerConfig) Allow(r *Request) (*Allowed, error) {
	t := TypeByName(r.Type)
	if t == nil {
		return nil, fmt.Errorf("unknown action type %q", r.Type)
	}
	if t.Where != OnServer {
		return nil, fmt.Errorf("%s does not run on a server", t.Name)
	}
	a := &Allowed{Type: t, Request: r}
	used := map[string]bool{}
	arg := func(name string) (string, error) {
		v, ok := r.Args[name]
		if !ok {
			return "", fmt.Errorf("%s: missing argument %s", t.Name, name)
		}
		used[name] = true
		return v, nil
	}
	for _, p := range t.Params {
		v, err := arg(p.Name)
		if err != nil {
			return nil, err
		}
		notAllowed := fmt.Errorf("%s: %s=%s is not allowed on %s", t.Name, p.Name, v, c.Node)
		switch p.Source {
		case FromFixed:
			if !contains(p.Enum, v) {
				return nil, fmt.Errorf("%s: %s must be one of %s", t.Name, p.Name, strings.Join(p.Enum, ", "))
			}
		case FromContainers, FromRestartable:
			for i := range c.Containers {
				if c.Containers[i].Name == v && (p.Source == FromContainers || c.Containers[i].Restart) {
					a.Container = &c.Containers[i]
				}
			}
			if a.Container == nil {
				return nil, notAllowed
			}
		case FromUnits, FromRestartUnit:
			for i := range c.Units {
				if c.Units[i].Name == v && (p.Source == FromUnits || c.Units[i].Restart) {
					a.Unit = &c.Units[i]
				}
			}
			if a.Unit == nil {
				return nil, notAllowed
			}
		case FromLogs:
			for i := range c.Logs {
				if c.Logs[i].ID == v {
					a.Log = &c.Logs[i]
				}
			}
			if a.Log == nil {
				return nil, notAllowed
			}
		case FromTargets:
			if !contains(c.TCPTargets, v) {
				return nil, notAllowed
			}
			a.Target = v
		case FromPorts:
			n, err := strconv.Atoi(v)
			if err != nil || strconv.Itoa(n) != v {
				return nil, notAllowed
			}
			for _, p := range c.Ports {
				if p == n {
					a.Port = n
				}
			}
			if a.Port == 0 {
				return nil, notAllowed
			}
		case FromWG:
			for i := range c.WG {
				if c.WG[i].Iface == v {
					a.WG = &c.WG[i]
				}
			}
			if a.WG == nil {
				return nil, notAllowed
			}
		case FromScriptsRead, FromScriptsChg:
			want := Read
			if p.Source == FromScriptsChg {
				want = Change
			}
			for i := range c.Scripts {
				if c.Scripts[i].ID == v && c.Scripts[i].Kind == want {
					a.Script = &c.Scripts[i]
				}
			}
			if a.Script == nil {
				return nil, notAllowed
			}
			for _, sp := range a.Script.Params {
				sv, err := arg(sp.Name)
				if err != nil {
					return nil, err
				}
				if !sp.Accepts(sv) {
					return nil, fmt.Errorf("%s %s: %s=%s is not allowed", t.Name, a.Script.ID, sp.Name, sv)
				}
				a.ScriptArgs = append(a.ScriptArgs, [2]string{sp.Name, sv})
			}
		default:
			return nil, fmt.Errorf("%s: parameter %s has no source", t.Name, p.Name)
		}
	}
	for k := range r.Args {
		if !used[k] {
			return nil, fmt.Errorf("%s: unexpected argument %s", t.Name, k)
		}
	}
	if t.Kind == Change {
		cd := t.Cooldown
		switch {
		case a.Container != nil && a.Container.Cooldown != "":
			cd = a.Container.Cooldown
		case a.Unit != nil && a.Unit.Cooldown != "":
			cd = a.Unit.Cooldown
		case a.Script != nil && a.Script.Cooldown != "":
			cd = a.Script.Cooldown
		}
		d, _ := time.ParseDuration(cd)
		a.Cooldown = d
	}
	return a, nil
}
